"""A constrained incident responder. Unknown details are never generated by an LLM."""
from __future__ import annotations

import json
import os
import re
import time
import urllib.error
import urllib.request
from datetime import datetime, timezone
from urllib.parse import urlsplit


def demo_brief() -> dict:
    now = int(time.time() * 1000)
    return {"name": "Demo User", "mode": "test", "status": "active", "expiresAt": now + 86400000,
            "location": {"latitude": 12.97, "longitude": 77.59, "accuracy": 20, "timestamp": now}}


class BriefSource:
    """Read a fresh owner-authenticated incident for each conversational turn."""
    def __init__(self, origin: str | None = None, token: str | None = None, incident_id: str | None = None):
        self.origin, self.token, self.incident_id = origin, token, incident_id
        if any([origin, token, incident_id]) and not all([origin, token, incident_id]):
            raise ValueError("Configure VOICE_BACKEND_URL, VOICE_OWNER_TOKEN, and VOICE_INCIDENT_ID together")
        if origin:
            url = urlsplit(origin)
            if url.username or url.password or url.query or url.fragment or url.path not in ("", "/"):
                raise ValueError("Voice backend must be an origin without credentials or paths")
            if url.scheme != "https" and not (url.scheme == "http" and url.hostname in ("localhost", "127.0.0.1", "::1")):
                raise ValueError("Use HTTPS for remote incident data")
            if not re.fullmatch(r"[a-fA-F0-9-]{36}", incident_id or ""):
                raise ValueError("Invalid incident ID")

    @classmethod
    def from_env(cls):
        return cls(os.getenv("VOICE_BACKEND_URL"), os.getenv("VOICE_OWNER_TOKEN"), os.getenv("VOICE_INCIDENT_ID"))

    def read(self) -> dict:
        if not self.origin:
            return demo_brief()
        request = urllib.request.Request(f"{self.origin.rstrip('/')}/api/incidents/{self.incident_id}/voice-brief",
                                         headers={"Authorization": f"Bearer {self.token}"})
        # Never forward the owner token through HTTP redirects.
        class NoRedirect(urllib.request.HTTPRedirectHandler):
            def redirect_request(self, *args, **kwargs):
                return None
        try:
            with urllib.request.build_opener(NoRedirect).open(request, timeout=5) as response:
                return json.loads(response.read(32768))
        except (urllib.error.URLError, TimeoutError, ValueError):
            return {"status": "unavailable"}


def response(brief: dict, question: str = "", now: int | None = None) -> str:
    now = int(time.time() * 1000) if now is None else now
    if brief.get("status") != "active" or brief.get("expiresAt", 0) <= now:
        return "The alert is ended, expired, or unavailable. I cannot confirm current details. Please verify with a human."
    prefix = "This is a test. " if brief.get("mode") == "test" else ""
    if re.search(r"\b(cancel|dispatched|dispatch|safe|resolved|close|officers)\b", question, re.I):
        return prefix + "I cannot confirm that help was dispatched or that the person is safe. I cannot dispatch officers or cancel a response. Please verify through a human operator."
    name = " ".join(str(brief.get("name", "A user")).split())[:80]
    if re.search(r"\b(who|attacker|suspect|weapon|involved)\b", question, re.I):
        return prefix + f"{name} activated the SOS. Other people involved, suspects, and weapons are unknown."
    if question and not re.search(r"\b(where|location|coordinate|coordinates|address|landmark|repeat|details|hello)\b", question, re.I):
        return prefix + "An SOS was activated requesting urgent police assistance. The nature of the incident is unknown. I can repeat the recorded location and the person's configured name."
    text = prefix + f"I am an automated safety assistant. {name} activated an SOS requesting urgent police assistance. The nature of the incident and other people involved are unknown. "
    position = brief.get("location")
    if not position:
        return text + "The location is unavailable. No address or landmark can be confirmed."
    timestamp = position.get("timestamp", 0)
    age = max(0, (now - timestamp) // 1000)
    recorded = datetime.fromtimestamp(timestamp / 1000, timezone.utc).strftime("%Y-%m-%d at %H:%M:%S UTC")
    return text + (f"The last reported coordinates are latitude {position['latitude']:.6f}, longitude {position['longitude']:.6f}, "
                   f"recorded {recorded}, approximately {age} seconds ago, with reported accuracy {round(position['accuracy'])} metres. "
                   + ("This position is stale and is not a confirmed current location. " if age > 60 else "")
                   + (f"The approximate mapped place is {' '.join(str(position['placeName']).split())[:180]}. No landmark has been independently verified." if position.get('placeName') else "No street address or landmark has been verified for this voice brief."))
